CAMEL = {slug: "".join([NAMES[slug].split("_")[0], *[x.title() for x in NAMES[slug].split("_")[1:]]]) for slug in SLUGS}
API = {
    "go": {slug:f"func {CAMEL[slug][0].upper()+CAMEL[slug][1:]}(input string) (string, bool)" for slug in SLUGS},
    "java": {slug:f"public static String {CAMEL[slug]}(String input)" for slug in SLUGS},
    "javascript": {slug:f"exports.{CAMEL[slug]} = function(input)" for slug in SLUGS},
    "typescript": {slug:f"export function {CAMEL[slug]}(input: string): string | null" for slug in SLUGS},
    "python": {slug:f"def {NAMES[slug]}(input: str) -> str | None" for slug in SLUGS},
    "rust": {slug:f"pub fn {NAMES[slug]}(input: &str) -> Option<String>" for slug in SLUGS},
}
FILE = {"go":"Return solution.go in package solution.","java":"Return Solution.java defining public final class Solution.","javascript":"Return CommonJS module solution.js.","typescript":"Return strict TypeScript module solution.ts.","python":"Return solution.py with the function at module scope.","rust":"Return solution.rs with the public function at module scope."}


def bad_source(language: str, slug: str) -> str:
    snake=NAMES[slug]; camel=CAMEL[slug]; go_name=camel[0].upper()+camel[1:]
    return {
        "go":f"package solution\nfunc {go_name}(input string)(string,bool){{return input,true}}\n",
        "java":f"public final class Solution{{public static String {camel}(String input){{return input;}}}}\n",
        "javascript":f"exports.{camel}=input=>input;\n",
        "typescript":f"export function {camel}(input:string):string|null{{return input}}\n",
        "python":f"def {snake}(input: str) -> str | None:\n return input\n",
        "rust":f"pub fn {snake}(input:&str)->Option<String>{{Some(input.to_string())}}\n",
    }[language]


def prompt_for(language: str, slug: str, kind: str, bad: str) -> str:
    head="Implement the following API." if kind=="generation" else "Repair the buggy source below without changing the required API."
    repair=f"\n\nBuggy source to repair:\n\n{bad.rstrip()}" if kind=="repair" else ""
    return f"{head}\n\nFile contract: {FILE[language]}\nRequired API: {API[language][slug]}\nBehavior: {BEHAVIOR[slug]}\nVisible example: {EXAMPLE[slug]}{repair}\n\nReturn only the complete source file; do not include Markdown fences or prose."


def typescript_reference(slug: str) -> tuple[str,str]:
    ref,check=JS[slug]
    ref=ref.replace("const f=s=>", "const f:(s:string)=>string|null=(s:string)=>")
    ref=ref.replace("ok=v=>", "ok=(v:string)=>")
    ref=ref.replace("v=x=>", "v=(x:string):number[]|null=>")
    ref=ref.replace("cmp=(a,b)=>", "cmp=(a:number[],b:number[])=>")
    return ref+f"\nexport function {CAMEL[slug]}(input:string):string|null{{return f(input)}}\n",check


def artifact(language: str, slug: str) -> tuple[str,str,str]:
    bad=bad_source(language,slug)
    if language=="python":
        ref,test=PY[slug]; test=f"from solution import {NAMES[slug]}\n"+test
        return ref,bad,test
    if language=="javascript":
        ref,check=JS[slug]; ref+=f"\nexports.{CAMEL[slug]}=f;\n"
        test=f"const{{{CAMEL[slug]}:f}}=require('./solution');if(!({check}))throw Error('contract');\n"
        return ref,bad,test
    if language=="typescript":
        ref,check=typescript_reference(slug)
        test=f"import{{{CAMEL[slug]} as f}}from'./solution';if(!({check}))throw Error('contract');\n"
        return ref,bad,test
    if language=="go":
        ref,check=GO[slug]; ref="package solution\n"+ref
        test="package solution\nimport \"testing\"\nfunc TestContract(t *testing.T){"+check+"}\n"
        return ref,bad,test
    if language=="java":
        ref,check=JAVA[slug]
        test="import java.util.*;public final class SolutionTest{public static void main(String[]z){if(!("+check+"))throw new AssertionError();}}\n"
        return ref+"\n",bad,test
    ref,check=RUST[slug]
    test="mod solution;use solution::*;#[test]fn contract(){"+check+"}\n"
    return ref+"\n",bad,test


def normalized(text: str) -> str:
    return " ".join(unicodedata.normalize("NFKC",text).casefold().split())


def comparison_prompts() -> tuple[set[str],set[str],dict[str,int]]:
    exact:set[str]=set();norm:set[str]=set();counts={"seed":0,"private_development":0,"prior_decision":0}
    for relative in SEED_PATHS:
        with (ROOT/relative).open(encoding="utf-8") as handle:
            for line in handle:
                text=json.loads(line)["messages"][0]["content"];exact.add(sha256_text(text));norm.add(sha256_text(normalized(text)));counts["seed"]+=1
    for label,paths in (("private_development",DEVELOPMENT_MANIFESTS),("prior_decision",PRIOR_DECISION_MANIFESTS)):
        for relative in paths:
            manifest=load_json(ROOT/relative);claimed=manifest["manifest_sha256"]
            if sha256_object({k:v for k,v in manifest.items() if k!="manifest_sha256"})!=claimed:raise RuntimeError(f"comparison manifest hash mismatch: {relative}")
            for entry in manifest["tasks"]:
                task=load_json(ROOT/entry["path"])
                if sha256_object(task)!=entry["sha256"]:raise RuntimeError(f"comparison task hash mismatch: {entry['task_id']}")
                text=task["prompt"]["text"];exact.add(sha256_text(text));norm.add(sha256_text(normalized(text)));counts[label]+=1
    return exact,norm,counts


def build() -> tuple[dict,dict]:
    OUT.mkdir(parents=True,exist_ok=True)
    tasks=[];counter=Counter()
    for language in RUNTIME:
        for slug,kind in zip(SLUGS,KINDS):
            ref,bad,test=artifact(language,slug);prompt=prompt_for(language,slug,kind,bad)
            files=[]
            if language=="go":
                mod="module private.invalid/ganesh/decision/tranche3\n\ngo 1.22\n";files.append({"path":"go.mod","role":"support","content":mod,"sha256":sha256_text(mod)})
            test_path={"go":"solution_test.go","java":"SolutionTest.java","javascript":"solution.test.js","typescript":"solution.test.ts","python":"test_solution.py","rust":"solution_test.rs"}[language]
            files.append({"path":test_path,"role":"test","content":test,"sha256":sha256_text(test)})
            timeout=60 if language in {"go","java","rust"} else 30
            task={"schema_version":"1.0","task_id":f"decision-t3-{language}-{slug}","surface":"decision","language":language,"family":LANGUAGE_FAMILY[language],"task_type":kind,"prompt":{"text":prompt,"sha256":sha256_text(prompt)},"rendered_prompt":{"text":prompt,"sha256":sha256_text(prompt)},"candidate_path":CANDIDATE_PATH[language],"files":files,"runtime_id":RUNTIME[language],"limits":{"timeout_seconds":timeout,"memory_mb":512,"cpus":1,"pids":64,"output_bytes":65536},"validation":{"reference":{"label":"author-reference","code":ref,"sha256":sha256_text(ref)},"known_bad":[{"label":"identity-instead-of-contract","code":bad,"sha256":sha256_text(bad)}]}}
            validate_task(task);tasks.append(task);counter[(language,kind)]+=1
    exact,norm,counts=comparison_prompts()
    exact_hits=[t["task_id"] for t in tasks if t["prompt"]["sha256"] in exact];norm_hits=[t["task_id"] for t in tasks if sha256_text(normalized(t["prompt"]["text"])) in norm]
    own_exact=[t["task_id"] for t in tasks if sum(x["prompt"]["sha256"]==t["prompt"]["sha256"] for x in tasks)>1]
    own_norm=[t["task_id"] for t in tasks if sum(normalized(x["prompt"]["text"])==normalized(t["prompt"]["text"]) for x in tasks)>1]
    if exact_hits or norm_hits or own_exact or own_norm:raise RuntimeError("decision tranche3 prompt overlap")
    entries=[]
    for task in tasks:
        path=OUT/f"{task['task_id']}.task.json";write_json(path,task);entries.append({"task_id":task["task_id"],"language":task["language"],"task_type":task["task_type"],"path":str(path.relative_to(ROOT)),"sha256":sha256_object(task),"prompt_sha256":task["prompt"]["sha256"],"rendered_prompt_sha256":task["rendered_prompt"]["sha256"]})
    manifest={"schema_version":"ganesh-mini-private-eval-manifest/v1","surface":"decision","tranche":"tranche3","status":"authored-unexecuted","task_count":len(tasks),"counts_by_lane":{l:{k:counter[(l,k)] for k in ("generation","repair")} for l in RUNTIME},"runtime_config":"configs/eval/runtimes.json","tasks":entries};manifest["manifest_sha256"]=sha256_object(manifest)
    overlap={"schema_version":"ganesh-mini-evaluation-overlap/v1","evaluation_manifest":str(MANIFEST.relative_to(ROOT)),"evaluation_manifest_sha256":manifest["manifest_sha256"],"comparison_inputs":{"seed_jsonl":list(SEED_PATHS),"private_development_manifests":list(DEVELOPMENT_MANIFESTS),"prior_decision_manifests":list(PRIOR_DECISION_MANIFESTS)},"seed_records_inspected":counts["seed"],"private_development_prompts_inspected":counts["private_development"],"prior_decision_prompts_inspected":counts["prior_decision"],"comparison_prompts_inspected":sum(counts.values()),"evaluation_prompts_inspected":len(tasks),"normalization":"NFKC + Unicode casefold + whitespace collapse","exact_prompt_overlaps":exact_hits,"normalized_prompt_overlaps":norm_hits,"within_tranche_exact_overlaps":own_exact,"within_tranche_normalized_overlaps":own_norm,"status":"passed"};overlap["report_sha256"]=sha256_object(overlap)
